vec3 hue2rgb(float hue){
hue=fract(hue);
return saturate(vec3(
abs(hue*6.-3.)-1.,
2.-abs(hue*6.-2.),
2.-abs(hue*6.-4.)
));
}
vec3 hsl2rgb(vec3 hsl){
if(hsl.y==0.){
return vec3(hsl.z); //Luminance.
}else{
float b;
if(hsl.z<.5){
b=hsl.z*(1.+hsl.y);
}else{
b=hsl.z+hsl.y-hsl.y*hsl.z;
}
float a=2.*hsl.z-b;
return a+hue2rgb(hsl.x)*(b-a);
}
}
