vec4 sdPoly(int index, in vec2 p)
{	
float fPolyCount = float(polyCount);
float slice = (float(index) / fPolyCount) + (1. / fPolyCount) * 0.5;
vec2 iUV = vec2(0., slice);
vec4 pI = texture2D(vertTex, iUV);
float pIX = pI.x;
float pIY = pI.y;
float pIZ = pI.z;
float fMaxVerts = float(maxVerts);
float fNumVerts = pIZ;
float factor = fNumVerts / fMaxVerts;
int iNumVerts = int(pIZ);
float d = dot(p-vec2(pIX, pIY),p-vec2(pIX, pIY));
float s = 1.0;
float nearest = 1000.;
float minX = 1000.;
float maxX = -1000.;
float minY = 1000.;
float maxY = -1000.;
for( int i=0, j=iNumVerts - 1; i < iNumVerts; j=i, i++ )
{
iUV = vec2((float(i) / (fNumVerts)) * factor, slice);
vec2 jUV = vec2((float(j) / (fNumVerts)) * factor, slice);
pIX = texture2D(vertTex, iUV).x;
pIY = texture2D(vertTex, iUV).y;
float pJX = texture2D(vertTex, jUV).x;
float pJY = texture2D(vertTex, jUV).y;
minX = min(minX, pIX);
maxX = max(maxX, pIX);
minY = min(minY, pIY);
maxY = max(maxY, pIY);
minX = min(minX, pJX);
maxX = max(maxX, pJX);
minY = min(minY, pJY);
maxY = max(maxY, pJY);
vec2 pJ = vec2(pJX, pJY);
vec2 pI = vec2(pIX, pIY);
vec2 e = pJ - pI;
vec2 w =    p - pI;
vec2 b = w - e*clamp( dot(w,e)/dot(e,e), 0.0, 1.0 );
d = min( d, dot(b,b) );
nearest = min(nearest, d);
bvec3 cond = bvec3( p.y>=pIY, p.y<pJY, e.x*w.y>e.y*w.x );
if( all(cond) || all(not(cond)) ) s*=-1.0;  
}
float localY = (p.y - minY) / (maxY - minY);
float localX = (p.x - minX) / (maxX - minX);
return vec4(s*sqrt(d), nearest, localY, localX);
}
